body:
Per @DarioSamo's suggestion, I tried these changes:

<details>
<summary>Patch</summary>

```diff
--- a/servers/rendering/renderer_rd/shaders/forward_mobile/scene_forward_mobile.glsl
+++ b/servers/rendering/renderer_rd/shaders/forward_mobile/scene_forward_mobile.glsl
@@ -967,7 +967,7 @@ layout(location = 0) out vec4 diffuse_buffer; //diffuse (rgb) and roughness
 layout(location = 1) out vec4 specular_buffer; //specular and SSS (subsurface scatter)
 #else

-layout(location = 0) out hvec4 frag_color;
+layout(location = 0) out vec4 frag_color;
 #endif // MODE_MULTIPLE_RENDER_TARGETS

 #endif // RENDER DEPTH
@@ -2182,14 +2182,14 @@ void main() {
 #else //MODE_MULTIPLE_RENDER_TARGETS

 #ifdef MODE_UNSHADED
-       frag_color = hvec4(albedo, alpha);
+       frag_color = vec4(albedo, alpha);
 #else // MODE_UNSHADED
-       frag_color = hvec4(emission + ambient_light + diffuse_light + direct_specular_light + indirect_specular_light, alpha);
+       frag_color = vec4(emission + ambient_light + diffuse_light + direct_specular_light + indirect_specular_light, alpha);
 #endif // MODE_UNSHADED

 #ifndef FOG_DISABLED
        // Draw "fixed" fog before volumetric fog to ensure volumetric fog can appear in front of the sky.
-       frag_color.rgb = mix(frag_color.rgb, fog.rgb, fog.a);
+       frag_color.rgb = mix(frag_color.rgb, vec3(fog.rgb), float(fog.a));
 #endif // !FOG_DISABLED

        // On mobile we use a UNORM buffer with 10bpp which results in a range from 0.0 - 1.0 resulting in HDR breaking
@@ -2211,6 +2211,6 @@ void main() {
        ndc.y = -ndc.y;
        hvec3 prev_ndc = hvec3(prev_screen_position.xyz / prev_screen_position.w);
        prev_ndc.y = -prev_ndc.y;
-       frag_color = hvec4(ndc - prev_ndc, half(0.0));
+       frag_color = vec4(ndc - prev_ndc, half(0.0));
 #endif
 }
```
</details>

That made the "SPIR-V Capability StorageInputOutput16 was declared" ones go away, but the "Result type component width must be 32 bits" ones are still there

Also per @DarioSamo's direction, this patch eliminates the other VVL error as well:

<details>
<summary>Patch</summary>

```diff
--- a/servers/rendering/renderer_rd/shaders/forward_mobile/scene_forward_mobile.glsl
+++ b/servers/rendering/renderer_rd/shaders/forward_mobile/scene_forward_mobile.glsl
@@ -1482,8 +1482,8 @@ void main() {
        if (sc_scene_roughness_limiter_enabled()) {
                //https://www.jp.square-enix.com/tech/library/pdf/ImprovedGeometricSpecularAA.pdf
                half roughness2 = roughness * roughness;
-               hvec3 dndu = dFdx(normal), dndv = dFdy(normal);
-               half variance = half(scene_data.roughness_limiter_amount) * (dot(dndu, dndu) + dot(dndv, dndv));
+               vec3 dndu = dFdx(vec3(normal)), dndv = dFdy(vec3(normal));
+               half variance = half(scene_data.roughness_limiter_amount) * half(dot(dndu, dndu) + dot(dndv, dndv));
                half kernelRoughness2 = min(half(2.0) * variance, half(scene_data.roughness_limiter_limit));
                half filteredRoughness2 = min(half(1.0), roughness2 + kernelRoughness2);
                roughness = sqrt(filteredRoughness2);
```
</details>

I'll leave it to Dario to make these test changes into real changes :-)
